using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Runtime.CompilerServices;
using Hardlight.AutoGenerated;
using NUnit.Framework;
using Unity.IL2CPP.CompilerServices;

namespace ProjectLucid.Tests
{
    // Behaviour of Hardlight.AutoGenerated.HardlightEnumExtensions (HLModernUI.Runtime
    // 02000050, 060001e5..060001e6) and HardlightUIModernEnumComparers (0200004f,
    // 060001e3..060001e4), from the 1.10.1 x86-64 bodies. The UIWidgetEventType map is
    // shared static state; every case that can write to it holds a StaticDictionaryLease.
    [TestFixture]
    public sealed class OriginalModernUIEnumExtensionsTests
    {
        private static readonly Type Extensions = typeof(Hardlight.AutoGenerated.HardlightEnumExtensions);

        private static Dictionary<UIWidgetEventType, string> Map() =>
            (Dictionary<UIWidgetEventType, string>)Extensions.GetField("UIWidgetEventTypeEnumToString", BindingFlags.NonPublic | BindingFlags.Static).GetValue(null);

        private static int[] Options(Type type) => type.GetCustomAttributesData()
            .Where(a => a.AttributeType == typeof(Il2CppSetOptionAttribute))
            .Select(a => (int)a.ConstructorArguments[0].Value).ToArray();

        // Metadata 02000050: a beforefieldinit static class with one private static,
        // non-readonly map and the GetString extension. 0200004f: a constructible
        // beforefieldinit class with a public static readonly comparer.
        [Test]
        public void DeclarationsKeepTheOriginalShapes()
        {
            Assert.That(Extensions.IsAbstract && Extensions.IsSealed, Is.True, "static class");
            Assert.That(Extensions.Attributes.HasFlag(TypeAttributes.BeforeFieldInit), Is.True);
            Assert.That(Options(Extensions), Is.EqualTo(new[] { (int)Option.NullChecks, (int)Option.ArrayBoundsChecks }));
            FieldInfo map = Extensions.GetField("UIWidgetEventTypeEnumToString", BindingFlags.NonPublic | BindingFlags.Static);
            Assert.That(map.IsPrivate && !map.IsInitOnly, Is.True);
            MethodInfo getString = Extensions.GetMethod("GetString", BindingFlags.Public | BindingFlags.Static);
            Assert.That(getString.IsDefined(typeof(ExtensionAttribute), false), Is.True);
            Assert.That(getString.GetParameters().Single().ParameterType, Is.EqualTo(typeof(UIWidgetEventType)));

            Type comparers = typeof(HardlightUIModernEnumComparers);
            Assert.That(comparers.IsAbstract || comparers.IsSealed, Is.False);
            Assert.That(comparers.Attributes.HasFlag(TypeAttributes.BeforeFieldInit), Is.True);
            Assert.That(Options(comparers), Is.EqualTo(new[] { (int)Option.ArrayBoundsChecks, (int)Option.NullChecks }));
            FieldInfo comparer = comparers.GetField("UIWidgetEventTypeComparer");
            Assert.That(comparer.IsPublic && comparer.IsStatic && comparer.IsInitOnly, Is.True);
            Assert.That(comparer.FieldType, Is.EqualTo(typeof(UIWidgetEventTypeEqualityComparer)));
            Assert.That(new HardlightUIModernEnumComparers(), Is.Not.Null);
        }

        // .cctor 0x1A4A250 reads HardlightUIModernEnumComparers.UIWidgetEventTypeComparer
        // (whose .cctor 0x1A4A0C0 allocates it) for the Dictionary constructor, then adds the
        // one literal 0x2d98edc7 with "Selection".
        [Test]
        public void StaticMapUsesTheModernUIComparerAndTheSelectionEntry()
        {
            Dictionary<UIWidgetEventType, string> map = Map();
            Assert.That(HardlightUIModernEnumComparers.UIWidgetEventTypeComparer, Is.Not.Null);
            Assert.That(map.Comparer, Is.SameAs(HardlightUIModernEnumComparers.UIWidgetEventTypeComparer));
            Assert.That(map.First(), Is.EqualTo(new KeyValuePair<UIWidgetEventType, string>((UIWidgetEventType)0x2d98edc7, "Selection")));
            Assert.That(UIWidgetEventType.Selection.GetString(), Is.EqualTo("Selection"));
        }

        // GetString 0x1A4A140: TryGetValue first; a miss boxes the value, formats "0x{0:X}"
        // (eight padded Int32 digits for an enum) and stores it with set_Item, so the
        // second call returns the cached instance.
        [Test]
        public void UnmappedValuesFormatAsPaddedHexAndAreCached()
        {
            var probe = (UIWidgetEventType)0x2B;
            using (new VerificationFixtureOwnership.StaticDictionaryLease(Extensions, "UIWidgetEventTypeEnumToString"))
            {
                Dictionary<UIWidgetEventType, string> map = Map();
                Assert.That(map.ContainsKey(probe), Is.False, "fixture requires an unmapped value");
                string first = probe.GetString();
                Assert.That(first, Is.EqualTo("0x0000002B"));
                Assert.That(map[probe], Is.SameAs(first));
                Assert.That(probe.GetString(), Is.SameAs(first));
                Assert.That(((UIWidgetEventType)(-1)).GetString(), Is.EqualTo("0xFFFFFFFF"));

                map[UIWidgetEventType.Selection] = "Replaced";
                Assert.That(UIWidgetEventType.Selection.GetString(), Is.EqualTo("Replaced"), "the current map entry is returned");
            }
            Assert.That(Map().ContainsKey(probe), Is.False, "the lease removed the cached miss");
            Assert.That(UIWidgetEventType.Selection.GetString(), Is.EqualTo("Selection"));
        }
    }
}
